static long _file_mtime(const char *path) {
  struct stat st;
  if (stat(path, &st) == 0) return (long)st.st_mtime;
  return -1;
}
static int _file_exists(const char *path) {
  struct stat st;
  return stat(path, &st) == 0 ? 1 : 0;
}
